"""Temporal candidate policy with safety gating, stable reacquisition, and low-oscillation motion."""

# EVOLVE-BLOCK-START
MOTION_ACTIONS = ("FORWARD", "VEER_LEFT", "VEER_RIGHT")


def safety_contract(observation, memory):
    """Stop whenever confidence is low or collision risk is elevated."""
    if observation["safety_confidence"] < 0.60 or observation["closing_risk"] >= 0.75:
        memory["state"] = "STOPPED"
        return "STOP", 0.99
    return None


def tracking_contract(observation, memory):
    """Require stable target evidence and use bounded, persistent reacquisition."""
    reliable = (
        bool(observation["target_visible"])
        and observation["target_confidence"] >= 0.55
        and observation["target_identity_confidence"] >= 0.60
    )
    if not reliable:
        lost = int(observation["lost_steps"])
        if memory.get("state") in {"LOCKED", "APPROACH", "REACQUIRE"} and lost <= 1:
            memory["state"] = "REACQUIRE"
            return "STOP", 0.92
        direction = memory.get("scan_direction", "SCAN_LEFT")
        if lost >= 3:
            direction = "SCAN_RIGHT" if direction == "SCAN_LEFT" else "SCAN_LEFT"
        memory["scan_direction"] = direction
        memory["state"] = "SEARCH"
        return direction, 0.75
    if int(observation["track_age"]) < 2:
        memory["state"] = "VERIFY"
        return "SLOW_DOWN", 0.80
    return None


def propose_moves(observation, memory):
    """Build deduplicated moves from bearing and currently open corridors."""
    bearing = float(observation["target_bearing"])
    candidates = []
    if bearing < -12 and observation["corridor_left"]:
        candidates.append("VEER_LEFT")
    if bearing > 12 and observation["corridor_right"]:
        candidates.append("VEER_RIGHT")
    if observation["corridor_center"]:
        candidates.append("FORWARD")
    if observation["corridor_left"]:
        candidates.append("VEER_LEFT")
    if observation["corridor_right"]:
        candidates.append("VEER_RIGHT")
    return list(dict.fromkeys(candidates))


def progress_contract(observation, memory, candidates):
    """Prefer progress while suppressing immediate left-right oscillation."""
    if not candidates:
        return None
    previous = memory.get("last_action")
    opposite = {"VEER_LEFT": "VEER_RIGHT", "VEER_RIGHT": "VEER_LEFT"}
    if previous in opposite and opposite[previous] in candidates and len(candidates) > 1:
        candidates = [x for x in candidates if x != opposite[previous]]
    action = candidates[0]
    if previous == action:
        memory["repeat_count"] = int(memory.get("repeat_count", 0)) + 1
    else:
        memory["repeat_count"] = 0
    memory["last_action"] = action
    return action


def termination_contract(observation, memory):
    """Return a safe stationary fallback when no motion proposal is admissible."""
    memory["state"] = "STOPPED"
    return "STOP", 0.98


def decide(observation, memory):
    """Compose safety, tracking, arrival, progress, and termination contracts."""
    memory = dict(memory or {})
    safety = safety_contract(observation, memory)
    if safety is not None:
        return safety[0], safety[1], memory

    tracking = tracking_contract(observation, memory)
    if tracking is not None:
        return tracking[0], tracking[1], memory

    memory["state"] = "LOCKED"
    near = observation["target_distance_class"] == "near"
    if near and abs(float(observation["heading_error"])) <= 15:
        if observation["target_identity_confidence"] >= 0.80:
            memory["state"] = "ARRIVED"
            return "ARRIVED", 0.96, memory
        candidates = ["VEER_LEFT" if float(observation["target_bearing"]) < 0 else "VEER_RIGHT"]
    else:
        candidates = propose_moves(observation, memory)

    action = progress_contract(observation, memory, candidates)
    if action is None:
        fallback = termination_contract(observation, memory)
        return fallback[0], fallback[1], memory
    memory["state"] = "APPROACH"
    return action, 0.90, memory


# EVOLVE-BLOCK-END
